update public.site_settings set value = jsonb_set(value, '{success_msg}', '{"ru": "Сохраните ваш персональный QR-код. Он будет использоваться для регистрации участников при входе в день конференции.", "en": "Please save your personal QR code. It will be used for registration at the entrance on the day of the conference.", "kg": "Өзүңүздүн жеке QR-кодуңузду сактап коюңуз. Ал конференция күнү кире бериште катышуучуларды каттоо үчүн колдонулат."}'::jsonb) where key = 'register_page';